      "answer": "巴洛克文学是17世纪主要文学思潮之一。产生与罗马天主教会发动的反宗教改革运动关系密切。它们采取强有力的反制措施，修建了大量造型独特的教堂，传递强烈的宗教情感鼓舞教民，增强天主教的凝聚力和感染力。巴洛克建筑风格很快在文艺复兴运动晚期引起了社会动荡、思想混乱和人心迷茫，精神消沉。涉及范围非常广泛，在建筑、绘画、雕塑、音乐、文学等领域具有突出表现。最著名的巴洛克风格文学家：卡尔德隆《人生如梦》（西班牙）。",
