      "answer": "古典主义是法国17世纪文学的主潮，形成和繁荣于法国，随后扩展到欧洲其他国家。是新兴资产阶级与封建贵族在政治上妥协的产物。在思想艺术上，拥护王权、尊崇理性、以古希腊罗马文学为典范、要求文学形式遵从规范。以戏剧成就最突出，产生高乃依、拉辛、莫里哀等杰出剧作家；古典主义诗歌以寓言诗人拉封丹一枝独秀；布瓦洛以古典主义理论总结著名。",
