      "answer": "《熙德》是古典主义悲剧的奠基人高乃依创作的作品。贵族青年罗迪克和贵族小姐施曼娜相爱，但他们的父辈发生争执，在两个青年人中引发了情与理的冲突。罗迪克在决斗中杀死了情人的父亲，施曼娜要求国王处死罗迪克以报父仇。正在此时，外敌入侵，罗迪克率众抗敌，取得胜利，被呼为“熙德”成为民族英雄。男女主人公经过国王调和最终妥协，是17世纪封建贵族阶级利益与资产阶级利益相互妥协的反映。",
