      "answer": "《安德洛玛克》是古典主义悲剧作家拉辛创作的一部五幕诗剧，情节取自希腊神话传说。作品谴责贵族阶级为了欲望而置国家利益与义务于不顾，颂扬忠于祖国、忠于爱情的自我牺牲精神。安德洛玛克凭借高度的理性和毅力，最终战胜了邪恶势力成为胜利者。主要人物有安德洛玛克（赫克托尔遗孀）；波洛斯（阿喀琉斯之子）；赫尔弥俄涅（希腊公主）。",
