      "answer": "《寓言诗》法国古典主义代表拉封丹创作的作品。通过改造动物故事，折射出法国社会现实；部分寓言富含人生哲理，并具有一定讽刺性。诗体优雅，是17世纪叙事艺术的典范之作。拉·封丹的寓言，与《伊索寓言》、《克雷洛夫寓言诗》一起，构成了世界寓言作品中最高的三座丰碑。其中的名篇，如《狼和小羊》《乌鸦和狐狸》等在世界许多国家都广为流传。",
