      "answer": "《悭吝人》，又译《吝啬鬼》，是法国古典主义作家莫里哀创作的喜剧。取材古罗马喜剧《一罐金子》。刻画了一个爱财如命的富商、高利贷者阿巴贡。阿巴贡有资本主义发展初期资产者敛钱方式与活动特点，是欧洲文学史著名吝啬鬼。细节积累刻画其性格：克扣子女花费，吞没其继承的母亲遗产；用八人饭菜招待十人；不担儿女结婚费用，还要亲家做礼服；放二分五厘高利贷，并以破烂实物抵一部分现金。",
