      "answer": "《伪君子》是法国古典主义作家莫里哀最优秀的喜剧，也是欧洲古典喜剧中成就最高的作品。作品写宗教骗子答丢夫骗取富商奥尔恭的信任，几乎使其倾家荡产，暴露出伪君子、假虔徒的真面目。深刻揭露了教会势力的虚伪性和欺骗性。全剧结构严谨，运用夸张和对比突出人物的主导性格，基本按照古典主义原则创作，但又有所突破，在喜剧中加入悲剧因素，使矛盾更加尖锐，社会批判性更加突出。",
