      "answer": "第一，拥护王权。在政治思想上主张国家统一，反对封建割据，歌颂英明的国王，把文学和现实政治结合得非常紧密。古典主义作品大多描写主人公的感情与家族责任或国家义务的冲突，表现感情服从责任，个人服从义务的主题。不少作品直接歌颂国王贤明。\n第二，尊崇理性。宣扬理性，要求克制个人情欲。要以理性去处理个人与国家利益、家庭义务和荣誉观念的矛盾，因而爱情或情欲只能放在第二位。\n第三，以古希腊罗马文学为典范。从其中汲取艺术形式和题材。古典主义戏剧与古希腊古罗马的悲剧和喜剧已有很大不同，已具备现代戏剧的基本形式，有一定的幕数，适宜于在一定的时间内演出。戏剧冲突十分尖锐，心理刻画细腻，达到悲剧和喜剧新高峰。\n第四，要求文学形式遵从规范。例如戏剧创作要遵守“三一律”，即情节、时间、地点必须保持“整一”：须围绕单一的剧情进行，排除一切次要的插曲；在一天中进行；在一个地点进行。",
