      "answer": "《伪君子》基本按照古典主义原则创作，但又有所突破。（三一律）\n剧情从开始克雷央特要给主人道个“早安”，到法庭执达吏郑直先生说要带十个人来此过夜，时间始终没有超过二十四小时。地点也一直在奥尔恭家里，但莫里哀能利用这个集中的室内环境巧妙构思，如第三幕达米斯套间偷听，第四幕奥尔恭藏于桌下，都是利用室内环境设置的关键性情节。《伪君子》歌颂王权，从丧失理性的恶果证明理性的重要，也是符合古典主义原则的。\n该剧对古典原则又有所突破。比如在喜剧中加入了悲剧成份。答丢夫所造成的后果是悲剧性的：年青人的婚姻被破坏，奥尔恭差点倾家荡产身败名裂。虽不符合法规，却使剧情跌宕起伏，更加扣人心弦。莫里哀还汲取了民间戏剧艺术的因素，如打耳光、桌下藏人、家庭吵架、父子反目、隔墙偷听、情人拌嘴等，增强了喜剧的表现效果。",
